let stream=null,cleanup=()=>{},route='';
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function read(k,d){try{return JSON.parse(localStorage.getItem('serena-'+k))||d}catch{return d}}
function save(k,v){try{localStorage.setItem('serena-'+k,JSON.stringify(v))}catch{toast('设备空间不足，请先下载作品')}}
function stopCamera(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null}
function download(c,name){c.toBlob(b=>{if(!b){toast('图片导出失败，请重试');return}let u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);toast('作品已生成 ♡ 手机可在下载列表查看')},'image/png')}
function palette(id){return `<div class="row" id="${id}">${colors.map(c=>`<button class="swatch" data-color="${c}" style="background:${c}" aria-label="选择 ${c}"></button>`).join('')}</div>`}
