<button class="toy letter-toy" aria-label="进入 Letter Lab" onclick="location.hash='letters'">${svg(`<g transform="rotate(-9 120 80)"><rect x="18" y="16" width="196" height="135" rx="5" fill="#C9E5D3" stroke="#66534E" stroke-width="2"/><rect x="31" y="23" width="174" height="120" fill="#FFF8F0"/><path d="M47 42H195M47 64H195M47 86H195M47 108H195M47 130H195" stroke="#BED9ED"/><path d="M63 125V26" stroke="#F4B9CF"/><text x="87" y="85" font-size="52" font-family="Georgia" font-style="italic" fill="#D94F58">Aa</text><text x="98" y="124" font-size="12" fill="#66534E">little letter lab</text><path d="M30 35H44M30 62H44M30 89H44M30 116H44" stroke="#66534E" stroke-width="3" stroke-linecap="round"/></g><path d="M194 15L156 139L167 150L207 21Z" fill="#F5E4A7" stroke="#66534E" stroke-width="2"/><path d="M156 139L155 160L167 150" fill="#66534E"/>`,240,180)}<span class="tag">02 · 写一套自己的字 ↗</span></button>
